    G(3,3)=GG; G(4,4)=GG; G(5,5)=GG;

    // Build C_i (6x3) for each node i (0-indexed)
    Matrix<double,6,3> Cmat[4];
    for (int i=0;i<4;i++){
        double b = Minv(i,1); // dN_i/dx
        double c = Minv(i,2); // dN_i/dy
        double d = Minv(i,3); // dN_i/dz
        Matrix<double,6,3> C = Matrix<double,6,3>::Zero();
        C(0,0)=b;
        C(1,1)=c;
        C(2,2)=d;
        C(3,1)=d; C(3,2)=c;
        C(4,0)=d; C(4,2)=b;
        C(5,0)=c; C(5,1)=b;
        Cmat[i]=C;
    }

    double V = std::fabs(detM)/6.0;

    Matrix<double,12,12> K = Matrix<double,12,12>::Zero();
    for (int i=0;i<4;i++){
        for (int j=0;j<4;j++){
            Matrix3d Kij = Cmat[i].transpose() * G * Cmat[j] * V;
            K.block<3,3>(3*i,3*j) = Kij;
        }
    }

    std::cout << std::setprecision(10);
    std::cout << "{\"stiffness_matrix\":[";
    for (int r=0;r<12;r++){
        std::cout << "[";
        for (int c=0;c<12;c++){
            std::cout << std::scientific << K(r,c);
            if (c<11) std::cout << ",";
        }
        std::cout << "]";
        if (r<11) std::cout << ",";
    }
    std::cout << "]}" << std::endl;

    return 0;
}
